 need(1<=a.memory_gib<=24 and a.cpu in os.sched_getaffinity(0),'bounded actual worker');available=int(next(x.split()[1]for x in Path('/proc/meminfo').read_text().splitlines()if x.startswith('MemAvailable:')))*1024;need(available>=(512+a.memory_gib)*(1<<30),'actual host reserve')
 mp=a.manifest.resolve();d=read(mp);lr=a.local_result.resolve();r=read(lr)
 need(d['schema']=='RAMANUJAN_LOCAL_REAL_CELLS_PROPOSAL_V1'and d['status']=='UNTRUSTED_REQUIRES_ALL_KERNEL_CHECKS_AND_SOURCE_BASE_PAIR','exact proposal');need(d['bases']==[38358837683,14111427770]and d['unchanged_base_values']==[1644673232,632207037]and d['widths'][0]==a.width and 56<=a.width<=1000000,'locked owner range/base universe');need(d['stop']==38358837683+a.width+1,'closed integer window endpoint');need(sha(d['local_manifest'])==d['local_manifest_sha256']==r['manifest_sha256']and r['status']=='COMPLETED_HOST_LOCAL_KERNEL_INCREMENT_PROOFS_BASE_PAIR_PENDING_NOT_SOURCE_PV_ALONE','completed exact local kernel prerequisites');need(r['widths']==d['widths'],'identical local scope')
 ns=d['namespace'];need(re.fullmatch(r'RamanujanPV\.[A-Za-z][A-Za-z0-9_]*',ns)is not None,'namespace');lns=read(d['local_manifest'])['namespace'];objects=Path(read(S/'BUILD_CONTEXT.json')['new_application_object_root'])
